const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
const received = String(headers['x-panoptes-webhook-secret'] ?? headers['X-Panoptes-Webhook-Secret'] ?? '');
const required = ['eventId', 'event', 'sourceId', 'projectId', 'documentId', 'title', 'url', 'chunkCount'];
const missing = required.filter((key) => body[key] === undefined || body[key] === null || body[key] === '');
const authorized = Boolean(expected) && received === expected;
const valid = body.event === 'source.ingested' && missing.length === 0 && Number.isInteger(Number(body.chunkCount)) && Number(body.chunkCount) > 0;
return [{ json: { ...body, authorized, valid, ok: authorized && valid, error: !authorized ? 'Unauthorized' : missing.length ? `Missing fields: ${missing.join(', ')}` : valid ? null : 'Invalid payload' } }];

const data = $getWorkflowStaticData('global');
const events = data.events ?? {};
const now = Date.now();
for (const [id, timestamp] of Object.entries(events)) {
  if (now - Number(timestamp) > 86400000) delete events[id];
}
const duplicate = Boolean(events[$json.eventId]);
events[$json.eventId] = now;
data.events = events;
return [{ json: { ...$json, duplicate, accepted: true } }];
